30		Known     bool // false: the lookup failed; interface and gateway are undetermined
31		Interface string
32		Source    netip.Addr // invalid: the stack did not say
33		Gateway   netip.Addr // invalid: directly connected
34	}
35	
36	// pathStep is one row of the Path column.
37	type pathStep struct {
38		Kind      pathStepKind
39		Container pathContainer // stepContainer, stepNetwork, stepTrace
40		Route     pathRoute     // stepInterface, stepGateway
41		Hop       nettrace.Hop  // stepHop
42	}
43	
44	const (
45		sourceLabel       = "this machine"
46		routeUndetermined = "undetermined"
47		gatewayDirect     = "directly connected"
48	)
49	
50	// newPathRoute converts a route lookup into a pathRoute. A failed lookup
51	// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
52	func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
53		if err != nil {
54			return pathRoute{}
55		}
56		return pathRoute{
57			Known:     true,
58			Interface: hop.Interface,
59			Source:    addrFromIP(hop.Source),
60			Gateway:   addrFromIP(hop.Gateway),
61		}
62	}
63	
64	// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
65	func addrFromIP(ip net.IP) netip.Addr {
66		addr, ok := netip.AddrFromSlice(ip)
67		if !ok {
68			return netip.Addr{}
69		}
70		return addr.Unmap()
71	}
72	
73	// pathSteps returns the rows of the Path column: the source, then the
74	// interface and gateway when route is not nil, then the hops as selected by
75	// visiblePathHops. It returns nil while neither a route nor a hop exists.
76	// Neither input is modified.
77	func pathSteps(ctr *pathContainer, route *pathRoute, hops []nettrace.Hop) []pathStep {
78		if ctr == nil && route == nil && len(hops) == 0 {
79			return nil
80		}
81		var steps []pathStep
82		if ctr != nil {
83			steps = append(steps,
84				pathStep{Kind: stepContainer, Container: *ctr},
85				pathStep{Kind: stepNetwork, Container: *ctr},
86			)
87		}
88		steps = append(steps, pathStep{Kind: stepSource})
89		if route != nil {
90			steps = append(steps,
91				pathStep{Kind: stepInterface, Route: *route},
92				pathStep{Kind: stepGateway, Route: *route},
93			)
94		}
95		if ctr != nil {
96			steps = append(steps, pathStep{Kind: stepTrace, Container: *ctr})
97		}
98		for _, h := range visiblePathHops(hops) {
99			steps = append(steps, pathStep{Kind: stepHop, Hop: h})
100		}
101		return steps
102	}
103	
104	// hopCell is the TTL of a hop row; empty for the local rows.
105	func (s pathStep) hopCell() string {
106		if s.Kind != stepHop {
107			return ""
108		}
109		return strconv.Itoa(s.Hop.TTL)
110	}
111	
112	// stepCell names the kind of row.
113	func (s pathStep) stepCell() string {
114		switch s.Kind {
115		case stepContainer:
116			return "container"
117		case stepNetwork:
118			return "network"
119		case stepTrace:
120			return "trace"
121		case stepSource:
122			return "source"
123		case stepInterface:
124			return "interface"
125		case stepGateway:
126			return "gateway"
127		}
128		return s.Hop.Kind.String()
129	}
130	
131	// addressCell is the main text of the row.
132	func (s pathStep) addressCell() string {
133		switch s.Kind {
134		case stepContainer:
135			return s.Container.containerText()
136		case stepNetwork:
137			return s.Container.networkText()
138		case stepTrace:
139			return s.Container.traceText()
140		case stepSource:
141			return sourceLabel
142		case stepInterface:
143			return s.Route.interfaceText()
144		case stepGateway:
145			return s.Route.gatewayText()
146		}
147		return addrOrDash(s.Hop.Addr)
148	}
149	
150	// rttCell is the round-trip time of a hop that answered; "-" otherwise.
151	func (s pathStep) rttCell() string {
152		if s.Kind != stepHop {
153			return ""
154		}
155		if s.Hop.RTT <= 0 {
156			return "-"
157		}
158		return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
159	}
160	
161	// interfaceText is the interface name, followed by the source address when known.
162	func (r pathRoute) interfaceText() string {
163		if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
164			return routeUndetermined
165		}
166		name := r.Interface
167		if name == "" {
168			name = "unnamed"
169		}
170		if !r.Source.IsValid() {
171			return name
172		}
173		return name + " (" + r.Source.String() + ")"
174	}
175	
176	// gatewayText is the gateway address, or says the destination is directly connected.
177	func (r pathRoute) gatewayText() string {
178		switch {
179		case !r.Known:
180			return routeUndetermined
181		case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
182			return gatewayDirect
183		}
184		return r.Gateway.String()
185	}
186	
187	// addrOrDash formats an address, or "-" when there is none.
188	func addrOrDash(a netip.Addr) string {
189		if !a.IsValid() {
190			return "-"
191		}
192		return a.String()
193	}
