106	func TestPathStepsOrder(t *testing.T) {
107		unknown := &pathRoute{Known: false}
108		tests := []struct {
109			name  string
110			route *pathRoute
111			hops  []nettrace.Hop
112			want  []pathStepKind
113			hopTT []int // TTLs of the stepHop rows, in order
114		}{
115			{"nothing known yet", nil, nil, nil, nil},
116			{"route, no hop yet", stepsRoute, nil,
117				[]pathStepKind{stepSource, stepInterface, stepGateway}, nil},
118			{"criterion 1: source, interface, gateway, then sorted hops", stepsRoute,
119				[]nettrace.Hop{stepsHop3, stepsHop1},
120				[]pathStepKind{stepSource, stepInterface, stepGateway, stepHop, stepHop}, []int{1, 3}},
121			{"hop before route: the source still comes first", nil,
122				[]nettrace.Hop{stepsHop1},
123				[]pathStepKind{stepSource, stepHop}, []int{1}},
124			{"failed lookup keeps the three local rows", unknown,
125				[]nettrace.Hop{stepsHop1, stepsHop2},
126				[]pathStepKind{stepSource, stepInterface, stepGateway, stepHop, stepHop}, []int{1, 2}},
127			{"empty hop list", stepsRoute, []nettrace.Hop{},
128				[]pathStepKind{stepSource, stepInterface, stepGateway}, nil},
129			{"unresolved hops are dropped and the list is cut after the target", stepsRoute,
130				[]nettrace.Hop{
131					stepsHop3,
132					{TTL: 2, Kind: nettrace.HopUnresolved},
133					{TTL: 4, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("9.9.9.9")},
134					stepsHop1,
135				},
136				[]pathStepKind{stepSource, stepInterface, stepGateway, stepHop, stepHop}, []int{1, 3}},
137			{"the list is cut after an unreachable hop", stepsRoute,
138				[]nettrace.Hop{
139					stepsHop1,
140					{TTL: 3, Kind: nettrace.HopRouter, Addr: netip.MustParseAddr("9.9.9.9")},
141					{TTL: 2, Kind: nettrace.HopUnreachable, Addr: netip.MustParseAddr("10.0.0.1")},
142				},
